import json,sys,numpy as np
from pathlib import Path
p=Path(sys.argv[1]);m=json.loads((p/'s7-n3-phase-fields.json').read_text());f={(x['stage'],x['role']):x for x in m['frames']};out=[]
for stage in ['source-input','after-split','after-carry','after-remob-before-diffuse','after-fine-before-brush','after-brush-stable']:
 ps=f[stage,'pigment'];cs=f['source-color' if stage=='source-input' else stage,'color'];assert ps['mapping']==cs['mapping'] and ps['width']==cs['width'] and ps['height']==cs['height'];a=np.fromfile(p/ps['file'],dtype=np.uint8).astype(np.int16).reshape(-1,4);b=np.fromfile(p/cs['file'],dtype=np.uint8).astype(np.int16).reshape(-1,4);delta=b[:,3]-a[:,2];mass=a[:,2].sum(dtype=np.int64)*2/255;depth=b[:,:3].sum(axis=0,dtype=np.int64)*8/255;out.append({'stage':stage,'physicalBufferId':ps['bufferId'],'colorBufferId':cs['bufferId'],'colorAlphaMinusPigmentBCodes':{'nonzeroPixels':int((delta!=0).sum()),'positivePixels':int((delta>0).sum()),'negativePixels':int((delta<0).sum()),'min':int(delta.min()),'max':int(delta.max()),'globalNet':int(delta.sum())},'physicalBIntegral':float(mass),'depthRGBIntegral':depth.tolist(),'massWeightedTauRGB':(depth/max(mass,1e-9)).tolist(),'physicalRGBConeViolations':(a[:,:3]>a[:,3:4]).sum(axis=0).tolist(),'opticalRGBAConeViolations':(b>a[:,3:4]).sum(axis=0).tolist()})
q={'stageMetrics':out,'mapping':m['frames'][0]['mapping'],'scope':'Latest secondsettle; source split mobile only, aftercarry before remob. Framebuffers need eventID audit; no sum mobile+fixed except finalcombined.'};(p/'rich-pair-audit.json').write_text(json.dumps(q,indent=2));print(json.dumps(q))
